static const Map maps[] = {
	{ "s750", "S-750", { 0x34 }, 1, 4, blocks5, 5, entrys6, 961 },
	{ "s760", "S-760", { 0x34 }, 1, 4, blocks13, 8, entrys14, 1282 },
	{ "s770", "S-770", { 0x34 }, 1, 4, blocks5, 5, entrys6, 961 },
	{ "sp700", "SP-700", { 0x34 }, 1, 4, blocks18, 7, entrys19, 1026 },
};

const Block *Map::block(std::string_view id) const
{
	for (uint32_t n = 0; n < block_count; n++)
		if (id == blocks[n].id)
			return &blocks[n];
	return nullptr;
}

const Entry *Map::first(const Block *b) const
{
	for (uint32_t n = 0; n < entry_count; n++)
		if (&blocks[entries[n].block] == b)
			return &entries[n];
	return nullptr;
}

const Map *find(std::string_view id)
{
	for (const Map &m : maps)
		if (id == m.id)
			return &m;
	return nullptr;
}

const Map *all(size_t &count)
{
	count = sizeof maps / sizeof *maps;
	return maps;
}

